import { UpdateDimensionOperation } from './../../../sheet-js/src/sheet/operation/type';
import {
  BaseSheet,
  Sheet,
  Operation,
  InsertColOperation,
  RemoveColOperation,
  InsertRowOperation,
  RemoveRowOperation,
  ScatterRangeOperation,
  SortOperation,
  UpdateCellOperation,
} from '@bzl/sheet-js';
import { initialDoc, MOCK_DATA } from '../utils';
import { SheetOTType } from '../../src';
import { describe, expect, test, afterEach, beforeEach } from 'vitest';

const SORTBy = [
  {
    sortBy: 'sheet',
  },
  {
    sortBy: 'range',
  },
] as { sortBy: SortOperation['sortBy'] }[];

describe.each(SORTBy)(
  '测试OT冲突转换：left side to sort ($sortBy), right side to:',
  ({ sortBy }) => {
    let doc1: BaseSheet;
    let doc2: BaseSheet;
    const op1: SortOperation = {
      type: 'sort',
      id: '1',
      before: [1, 2, 3, 4, 5, 6, 7, 8, 9],
      after: [4, 3, 5, 6, 8, 7, 9, 1, 2],
      range: [4, 1, 4, 10],
      order: 'asc',
      sortBy,
    };
    let op2: Operation;

    beforeEach(() => {
      doc1 = initialDoc(MOCK_DATA) as Sheet;
      doc2 = initialDoc(MOCK_DATA) as Sheet;
    });

    afterEach(() => {
      const [op12, op21] = SheetOTType.transformX([op1], [op2]);
      doc1 = SheetOTType.apply(SheetOTType.apply(doc1, op1), op21);
      doc2 = SheetOTType.apply(SheetOTType.apply(doc2, op2), op12);
      console.log('op12', JSON.stringify(op12));
      console.log('op21', JSON.stringify(op21));
      console.log('doc1', JSON.stringify(doc1));
      console.log('doc2', JSON.stringify(doc2));
      expect(doc1).toEqual(doc2);
    });

    describe.concurrent('fill-range', () => {
      test('type = data', () => {
        op2 = {
          type: 'fill-range',
          range: [2, 0, 3, 1],
          fillBy: 'data',
          data: {
            value: -1,
          },
          id: '1',
        };
      });
      test('type = data (intersection)', () => {
        op2 = {
          type: 'fill-range',
          range: [3, 2, 4, 5],
          fillBy: 'data',
          data: {
            value: -1,
          },
          id: '1',
        };
      });
      test('type = style', () => {
        op2 = {
          type: 'fill-range',
          range: [3, 2, 4, 5],
          fillBy: 'style',
          style: {
            background: '#EFE1FA',
          },
          id: '1',
        };
      });
      test('type = clear', () => {
        op2 = {
          type: 'fill-range',
          range: [3, 2, 4, 5],
          fillBy: 'clear',
          style: {
            background: '#EFE1FA',
          },
          id: '1',
        };
      });
      test('type = border', () => {
        op2 = {
          type: 'fill-range',
          fillBy: 'border',
          range: [3, 2, 4, 5],
          site: {
            top: true,
            right: true,
            bottom: true,
            left: true,
            innerCol: true,
            innerRow: true,
          },
          id: '1',
        };
      });
    });

    describe.concurrent('insert-col', () => {
      test('at before', () => {
        op2 = {
          type: 'insert-col',
          at: op1.range[0] - 1,
          count: 2,
          id: '1',
        } as InsertColOperation;
      });

      test('at after', () => {
        op2 = {
          type: 'insert-col',
          at: op1.range[2] + 1,
          count: 2,
          id: '1',
        } as InsertColOperation;
      });
      test('at same', () => {
        op2 = {
          type: 'insert-col',
          at: op1.range[0],
          count: 2,
          id: '1',
        } as InsertColOperation;
      });
    });

    describe.concurrent('remove-col', () => {
      test('at same', () => {
        op2 = {
          type: 'remove-col',
          at: op1.range[0],
          count: 2,
          id: '1',
        } as RemoveColOperation;
      });
      test('intersection', () => {
        op2 = {
          type: 'remove-col',
          at: op1.range[0] - 1,
          count: 2,
          id: '1',
        } as RemoveColOperation;
      });
      test('no intersection', () => {
        op2 = {
          type: 'remove-col',
          at: op1.range[0] + 2,
          count: 2,
          id: '1',
        } as RemoveColOperation;
      });
    });

    describe.concurrent('insert-row', () => {
      describe('follow = after', () => {
        test('at before', () => {
          op2 = {
            type: 'insert-row',
            at: op1.range[1] - 1,
            count: 2,
            id: '1',
            follow: 'after',
          } as InsertRowOperation;
        });
        test('at after', () => {
          op2 = {
            type: 'insert-row',
            at: op1.range[3] + 1,
            count: 2,
            id: '1',
            follow: 'after',
          } as InsertRowOperation;
        });
        test('at same', () => {
          op2 = {
            type: 'insert-row',
            at: op1.range[3],
            count: 2,
            id: '1',
            follow: 'after',
          } as InsertRowOperation;
        });
      });
      describe('follow = before', () => {
        test('at before', () => {
          op2 = {
            type: 'insert-row',
            at: op1.range[1] - 1,
            count: 2,
            id: '1',
            follow: 'before',
          } as InsertRowOperation;
        });
        test('at after', () => {
          op2 = {
            type: 'insert-row',
            at: op1.range[3] + 1,
            count: 2,
            id: '1',
            follow: 'before',
          } as InsertRowOperation;
        });
        test('at same', () => {
          op2 = {
            type: 'insert-row',
            at: op1.range[3],
            count: 2,
            id: '1',
            follow: 'before',
          } as InsertRowOperation;
        });
      });
    });

    describe('remove-row', () => {
      test('at before', () => {
        op2 = {
          type: 'remove-row',
          at: op1.range[1] - 1,
          count: 2,
          id: '1',
        } as RemoveRowOperation;
      });
      test('at after', () => {
        op2 = {
          type: 'remove-row',
          at: op1.range[3] + 1,
          count: 2,
          id: '1',
        } as RemoveRowOperation;
      });
      test('at same', () => {
        op2 = {
          type: 'remove-row',
          at: op1.range[3],
          count: 2,
          id: '1',
        } as RemoveRowOperation;
      });
    });

    describe.concurrent('scatter-range', () => {
      test('style type', () => {
        op2 = {
          type: 'scatter-range',
          range: [2, 0, 3, 3],
          refs: {
            cells: [
              {
                children: [
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 0,
              },
              {
                children: [
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 0,
              },
              {
                children: [
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 0,
              },
              {
                children: [
                  {
                    index: 2,
                  },
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 0,
              },
              {
                children: [
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 1,
              },
              {
                children: [
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 1,
              },
              {
                children: [
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 1,
              },
              {
                children: [
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 1,
              },
              {
                children: [
                  {
                    index: 2,
                  },
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 1,
              },
              {
                children: [
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 1,
              },
              {
                children: [
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 1,
              },
              {
                children: [
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 2,
              },
              {
                children: [
                  {
                    index: 2,
                  },
                  {
                    meta: {
                      background: '#13C2C2',
                    },
                    index: 3,
                  },
                ],
                index: 2,
              },
              {
                index: 3,
                children: [
                  {
                    index: 2,
                  },
                  {
                    index: 3,
                  },
                ],
              },
            ],
            rows: [],
            cols: [],
            sheet: {},
          },
          scatterBy: 'style',
          id: '1',
        } as ScatterRangeOperation;
      });
      test('cell type', () => {
        op2 = {
          type: 'scatter-range',
          range: [0, 2, null, 2],
          refs: {
            cells: [
              {
                children: [
                  {
                    meta: {
                      type: 'number',
                      value: 2,
                    },
                    index: 1,
                  },
                ],
                index: 2,
              },
            ],
          },
          scatterBy: 'data',
          id: '1',
        } as ScatterRangeOperation;
      });
    });

    describe.concurrent('update-cell', () => {
      test('in sort range', () => {
        op2 = {
          type: 'update-cell',
          at: [op1.range[1] + 1, op1.range[0]],
          oldV: null,
          newV: {
            value: 2,
          },
          id: '1',
        } as UpdateCellOperation;
      });

      test('out of sort range', () => {
        op2 = {
          type: 'update-cell',
          at: [op1.range[3] + 1, op1.range[2] + 1],
          oldV: null,
          newV: {
            value: 2,
          },
          id: '1',
        } as UpdateCellOperation;
      });
    });

    describe.concurrent('update-dimension', () => {
      test('at before', () => {
        op2 = {
          type: 'update-dimension',
          meta: {
            size: 208,
          },
          section: {
            from: op1.range[1] - 1,
            to: op1.range[1] - 1,
            isRow: true,
          },
          id: '1',
        } as UpdateDimensionOperation;
      });

      test('at after', () => {
        op2 = {
          type: 'update-dimension',
          meta: {
            size: 208,
          },
          section: {
            from: op1.range[3] + 1,
            to: op1.range[3] + 1,
            isRow: true,
          },
          id: '1',
        } as UpdateDimensionOperation;
      });

      test('at same', () => {
        op2 = {
          type: 'update-dimension',
          meta: {
            size: 208,
          },
          section: {
            from: op1.range[1],
            to: op1.range[1],
            isRow: true,
          },
          id: '1',
        } as UpdateDimensionOperation;
      });

      test('at inner', () => {
        op2 = {
          type: 'update-dimension',
          meta: {
            size: 208,
          },
          section: {
            from: op1.range[1] + 1,
            to: op1.range[1] + 1,
            isRow: true,
          },
          id: '1',
        } as UpdateDimensionOperation;
      });
    });
  },
);
